function pSortLoad(){const sec=PERR?'perr':'prop';if(PSSEC===sec)return;PSSEC=sec;const c=PSC()||{};let s=null;try{s=JSON.parse(localStorage.getItem(pSortLS())||'null')}catch(_){}if(!s)s=c.default;if(s&&[...$('pso').options].some(o=>o.value===s.k)){$('pso').value=s.k;$('pdir').value=String(+s.d>0?1:-1)}}
function pSortSave(){try{localStorage.setItem(pSortLS(),JSON.stringify({k:$('pso').value,d:+$('pdir').value}))}catch(_){}}
function pSortSet(k){const c=PSC()||{};if($('pso').value===k)$('pdir').value=String(-(+$('pdir').value));else{$('pso').value=k;$('pdir').value=String(+c.first_dir>0?1:-1)}pSortSave();PSHOW=60;propRender()}
function pHead(cells){const c=PSC(),S=new Set(c?(c.cols||[]).map(x=>x.k):[]),k=$('pso').value,H=(c&&c.hint)||'';
return '<div class="pth">'+cells.map(([lab,cls,sk])=>{if(!sk||!S.has(sk))return `<span${cls?` class="${cls}"`:''}>${lab}</span>`;const on=k===sk;return `<button type="button" class="psh ${cls}${on?' on':''}" data-psk="${esc(sk)}" aria-sort="${on?(+$('pdir').value>0?'ascending':'descending'):'none'}" aria-label="${esc(H+' '+lab)}">${lab}<span class="par" aria-hidden="true">${esc(pArr(on)||'')}</span></button>`}).join('')+'</div>'}
function pChip(){const c=PSC();if(!c||!(c.cols||[]).length)return '';const k=$('pso').value,cur=(c.cols.find(x=>x.k===k)||{}).label||(($('pso').selectedOptions[0]||{}).textContent||'');
return `<div class="psort-m"><button type="button" class="pschip" id="pschip" aria-haspopup="listbox" aria-expanded="${PSOPEN?'true':'false'}">${esc(c.chip_label||'')}: <b>${esc(cur)} ${esc(pArr(1)||'')}</b></button>${PSOPEN?'<div class="pslist" role="listbox">'+c.cols.map(x=>`<button type="button" role="option" data-psk="${esc(x.k)}" class="${x.k===k?'on':''}" aria-selected="${x.k===k}"><span>${esc(x.label)}</span><span class="par">${esc(pArr(x.k===k)||'')}</span></button>`).join('')+'</div>':''}</div>`}
